# CSS add
css='''\n.researchcard{margin-bottom:14px;border-color:#5a4f86;background:linear-gradient(125deg,#102331,#171d36)}.researchhead{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.researchhead h2{margin:0;flex:1}.researchcontrols{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin:12px 0}.researchcontrols label{font-size:10px;color:#91aaba}.researchcontrols select,.researchcontrols input[type=number]{width:100%;margin-top:4px;padding:8px;border-radius:8px;border:1px solid #38586c;background:#081923;color:#edf6fb}.researchtoggle{display:flex;align-items:center;gap:7px;padding-top:18px}.researchactions{display:flex;gap:8px;flex-wrap:wrap}.researchprompt{width:100%;min-height:320px;margin-top:10px;padding:10px;border:1px solid #38586c;border-radius:9px;background:#071722;color:#dceef5;font:11px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace;resize:vertical}.researchmeta{font-size:11px;color:#9db3c0;margin-top:8px}.bridgeflow{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:9px;font-size:10px;color:#abc2d0}.bridgeflow b{padding:4px 7px;border-radius:999px;background:#222449;border:1px solid #514c7b}.bridgeflow i{font-style:normal;color:#7a87a4}@media(max-width:760px){.researchactions .btn{flex:1}.researchprompt{min-height:260px}}\n'''
