new=old+'''\n<section id="researchPanel" class="braincard researchcard"><div class="researchhead"><h2>🔬 AiO Research Bridge</h2><span id="researchState" class="pill">wartet auf Brain-Sync</span></div><p class="muted">Erzeugt aus vorhandenen D1-Lern-, Outcome- und Brain-Daten einen kompakten Prompt für eine übergeordnete ChatGPT-Analyse. Keine zusätzlichen Workers-AI-Neurons.</p><div class="bridgeflow"><b>Bot-Erfahrung</b><i>→</i><b>Relevanzfilter</b><i>→</i><b>Secret-Redaction</b><i>→</i><b>Analysebrief + JSON</b></div><div class="researchcontrols"><label>Analyseprofil<select id="researchProfile"><option value="development">Entwicklungsbrief</option><option value="overall">Gesamtanalyse</option><option value="errors">Fehleranalyse</option><option value="learning">Lernanalyse</option><option value="farm">Farmanalyse</option><option value="merchant">Merchant-Analyse</option></select></label><label>Zeitraum (Stunden)<input id="researchHours" type="number" min="1" max="168" value="24"></label><label class="researchtoggle"><input id="researchAnon" type="checkbox" checked> Charakternamen anonymisieren</label></div><div class="researchactions"><button class="btn alt" id="researchGenerate">Brief anzeigen</button><button class="btn" id="researchCopy">Prompt kopieren</button></div><div id="researchMeta" class="researchmeta">Der Web-Brief nutzt die sicher synchronisierten Daten. Lokale Roh-Auditlogs bleiben im Spielclient.</div><textarea id="researchPrompt" class="researchprompt" readonly hidden aria-label="AiO Research Prompt"></textarea></section>'''
assert old in d
d=d.replace(old,new,1)
# JS helper insertion before render(charsNow)
marker='function render(charsNow){const old=selectedMap;chars=charsNow;renderCards();renderMapSelect();if(!view||old!==selectedMap)fitMap();else renderMap();}'
assert marker in d
js=r'''function renderResearchState(b){const el=document.getElementById('researchState'),meta=document.getElementById('researchMeta');if(!el)return;const st=b&&b.ok&&Array.isArray(b.students)&&b.students[0]&&b.students[0].stats||{},r=st.research||{};if(r.enabled){el.textContent='bereit · '+(r.profileLabel||r.profile||'Analyse');el.className='pill live';if(meta)meta.textContent='Letzter sicherer Research-Sync: '+when(r.updatedAt)+' · '+Number(r.highlights||0)+' Highlights · '+Number(r.repeatedErrors||0)+' Fehlergruppen.';}else{el.textContent='wartet auf Brain-Sync';el.className='pill';}}
async function buildResearchBrief(){const profile=document.getElementById('researchProfile').value,hours=Math.max(1,Math.min(168,Number(document.getElementById('researchHours').value)||24)),anon=document.getElementById('researchAnon').checked?'1':'0',ta=document.getElementById('researchPrompt'),meta=document.getElementById('researchMeta');if(meta)meta.textContent='Research Bridge verdichtet D1-Daten …';const j=await api('/api/research-brief?profile='+encodeURIComponent(profile)+'&hours='+hours+'&anonymize='+anon);ta.value=j.prompt||'';ta.hidden=false;if(meta)meta.textContent=(j.profileLabel||profile)+' · '+hours+'h · '+(j.anonymized?'Namen anonymisiert':'Namen unverändert')+' · '+Number(j.data&&j.data.highlights&&j.data.highlights.length||0)+' Highlights · erzeugt '+new Date(j.generatedAt||Date.now()).toLocaleString();return ta.value;}
async function copyResearchBrief(){const text=await buildResearchBrief(),ta=document.getElementById('researchPrompt'),btn=document.getElementById('researchCopy');try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(text);btn.textContent='Kopiert ✓';setTimeout(()=>btn.textContent='Prompt kopieren',1600);return;}}catch{}ta.focus();ta.select();try{document.execCommand('copy');btn.textContent='Kopiert ✓';setTimeout(()=>btn.textContent='Prompt kopieren',1600);}catch{}}
'''
d=d.replace(marker,js+marker,1)
# load add renderResearchState
old="render(j.characters||[]);renderBrain(b);sync.textContent='aktualisiert '"
new="render(j.characters||[]);renderBrain(b);renderResearchState(b);sync.textContent='aktualisiert '"
assert old in d
d=d.replace(old,new,1)
# event bindings
old="document.getElementById('open').onclick=()=>{readKey=key.value.trim();sessionStorage.setItem('aioReadKey',readKey);load();};"
new="document.getElementById('researchGenerate').onclick=()=>buildResearchBrief().catch(e=>{document.getElementById('researchMeta').textContent='Fehler: '+e.message;});document.getElementById('researchCopy').onclick=()=>copyResearchBrief().catch(e=>{document.getElementById('researchMeta').textContent='Fehler: '+e.message;});\n"+old
assert old in d
d=d.replace(old,new,1)
d=d.replace('Die Gehirn-Übersicht zeigt den in D1 gespeicherten Teacher-/Student-Lernstand, Brain League, neuronalen Aktivitätszustand, Lernqualität/Selbstkontrolle und das überprüfbare Gehirn-Tagebuch.','Die Gehirn-Übersicht zeigt Teacher/Student, Brain League, Lernqualität und Tagebuch. Die Research Bridge erzeugt daraus sichere Analysebriefe für ChatGPT, ohne zusätzliche Workers-AI-Aufrufe.')
dashp.write_text(d)

# Worker additions
wp=root/'cloudflare-dashboard/src/worker.js'
w=wp.read_text()
w=w.replace('version:"2.13.0"','version:"2.14.0"')
w=w.replace('teacher-student-champion-challenger-diary-quality-guard','teacher-student-champion-challenger-diary-quality-research-bridge')
w=w.replace('number(input.version,9)','number(input.version,10)',1)
# insert helpers before studentSummary
marker='function studentSummary(payload){'
assert marker in w
helper=r'''function researchText(v,max=900){return text(v,max).replace(/\b(WRITE_KEY|READ_KEY|API[_-]?KEY|TOKEN|SECRET|AUTHORIZATION)\b\s*[:=]\s*[^\s,;]+/ig,"$1=[REDACTED]");}
function researchSummary(payload){const box=payload&&payload.research&&typeof payload.research==="object"?payload.research:{},r=box.summary&&typeof box.summary==="object"?box.summary:{},arr=(v,n)=>Array.isArray(v)?v.slice(0,n):[],safeErr=e=>e&&typeof e==="object"?{kind:researchText(e.kind,40),message:researchText(e.message,500),errorClass:researchText(e.errorClass,120),count:number(e.count),lastAt:number(e.lastAt),level:researchText(e.level,20)}:null,safeHi=e=>e&&typeof e==="object"?{at:number(e.at),kind:researchText(e.kind,40),title:researchText(e.title,180),detail:researchText(e.detail,700),action:researchText(e.action,40),target:researchText(e.target,80),reward:e.reward==null?null:number(e.reward),generation:number(e.generation)}:null,safeLesson=e=>e&&typeof e==="object"?{at:number(e.at),title:researchText(e.title,180),lesson:researchText(e.lesson,700),action:researchText(e.action,40),target:researchText(e.target,80)}:null,safeOutcome=e=>e&&typeof e==="object"?{at:number(e.at),title:researchText(e.title,180),detail:researchText(e.detail,700),reward:number(e.reward),action:researchText(e.action,40),target:researchText(e.target,80)}:null;const p=r.performance&&typeof r.performance==="object"?r.performance:{},q=r.quality&&typeof r.quality==="object"?r.quality:{},learning=r.learning&&typeof r.learning==="object"?r.learning:{};return {enabled:Boolean(box.schema===1||r.schema===1),profile:researchText(r.profile,24),profileLabel:researchText(r.profileLabel,80),generatedAt:number(r.generatedAt||box.updatedAt),updatedAt:number(box.updatedAt),windowHours:number(r.windowHours,24),anonymized:r.anonymized!==false,quality:{status:researchText(q.status,24),score:number(q.score),recentReward:number(q.recentReward),overconfidenceFailureRate:number(q.overconfidenceFailureRate)},performance:{xpPerHour:number(p.xpPerHour),goldPerHour:number(p.goldPerHour),xpGain:number(p.xpGain),goldGain:number(p.goldGain),freeSlots:number(p.freeSlots),inventorySlots:number(p.inventorySlots),farmSafetyPct:number(p.farmSafetyPct),visibleMonsters:number(p.visibleMonsters),competitors:number(p.competitors),partyComplete:Boolean(p.partyComplete)},repeatedErrors:arr(r.repeatedErrors,8).map(safeErr).filter(Boolean),highlights:arr(r.highlights,10).map(safeHi).filter(Boolean),teacherLessons:arr(r.teacherLessons,8).map(safeLesson).filter(Boolean),strongestOutcomes:arr(r.strongestOutcomes,8).map(safeOutcome).filter(Boolean),learning:{monsters:arr(learning.monsters,8).map(x=>x&&typeof x==="object"?{monster:researchText(x.monster,80),kills:number(x.kills),lootEvents:number(x.lootEvents),gold:number(x.gold),lastAt:number(x.lastAt)}:null).filter(Boolean),zones:arr(learning.zones,8).map(x=>x&&typeof x==="object"?{zone:researchText(x.zone,120),samples:number(x.samples),xpPerHour:number(x.xpPerHour),goldPerHour:number(x.goldPerHour),safetyPct:number(x.safetyPct),lastAt:number(x.lastAt)}:null).filter(Boolean)}};}
'''
w=w.replace(marker,helper+marker,1)
# add research in return studentSummary after diary field. Need exact suffix.
old='diary:diarySummary(payload)};\n}'
new='diary:diarySummary(payload),research:researchSummary(payload)};\n}'
assert old in w
w=w.replace(old,new,1)
# insert server research functions before handleBrainStatus
marker='async function handleBrainStatus(request,env){'
assert marker in w
server=r'''const RESEARCH_PROFILES={overall:{label:"Gesamtanalyse",task:"Bewerte den Gesamtzustand des AiO-Bots. Suche nach den wichtigsten Hebeln für 24/7-Stabilität, EXP/h, Gold/h, Lernqualität und Wartbarkeit."},errors:{label:"Fehleranalyse",task:"Analysiere wiederkehrende Fehler, Loops, Blockaden und Sicherheitsprobleme. Priorisiere konkrete Root Causes und robuste Code-Fixes."},learning:{label:"Lernanalyse",task:"Analysiere Student, Teacher, Champion/Challenger, Rewards, Kalibrierung und Lernqualität. Finde Falschlernen, Datenlücken und bessere Lernsignale."},farm:{label:"Farmanalyse",task:"Analysiere Farmziele, Zonen, Monster, Konkurrenz, EXP/h, Gold/h und Sicherheit. Schlage datenbegründete Verbesserungen der Farmstrategie vor."},merchant:{label:"Merchant-Analyse",task:"Analysiere Inventardruck, Versorgung, Bank, Upgrade/Compound, Verkauf, Wege und Merchant-Probleme. Suche nach 24/7-tauglichen Optimierungen."},development:{label:"Entwicklungsbrief",task:"Leite konkrete Änderungen für die nächste AiO-Bot-Version ab. Trenne deterministische Codeänderungen von Änderungen am neuronalen Brain und priorisiere nach Nutzen, Risiko und Testbarkeit."}};
function researchProfile(v){v=String(v||"development");return RESEARCH_PROFILES[v]?v:"development";}
function researchAliasMap(names,anonymize){const map={};let farmer=0,merchant=0;(names||[]).forEach(c=>{const name=String(c.name||"");if(!name)return;if(!anonymize){map[name]=name;return;}if(String(c.ctype||"")==="merchant"){merchant++;map[name]=merchant===1?"Merchant":"Merchant"+merchant;}else{farmer++;map[name]="Farmer"+farmer;}});return map;}
function researchReplaceNames(v,map){let s=researchText(v,1600);Object.keys(map||{}).sort((a,b)=>b.length-a.length).forEach(k=>{if(k&&map[k]!==k)s=s.split(k).join(map[k]);});return s;}
function researchMapObject(value,map,depth=0){if(depth>5)return null;if(Array.isArray(value))return value.slice(0,40).map(v=>researchMapObject(v,map,depth+1));if(value&&typeof value==="object"){const out={};Object.keys(value).slice(0,60).forEach(k=>{if(/key|token|secret|authorization|password/i.test(k))return;out[k]=researchMapObject(value[k],map,depth+1);});return out;}if(typeof value==="string")return researchReplaceNames(value,map);if(typeof value==="number"||typeof value==="boolean"||value==null)return value;return researchText(value,500);}
async function handleResearchBrief(request,env){if(!(await secretMatches(request.headers.get("x-aio-read-key"),env.READ_KEY)))return json({ok:false,error:"unauthorized"},401);await ensureAiTables(env);const url=new URL(request.url),profile=researchProfile(url.searchParams.get("profile")),hours=Math.max(1,Math.min(168,number(url.searchParams.get("hours"),24))),anonymize=url.searchParams.get("anonymize")!=="0",cutoff=Date.now()-hours*3600000;const sr=await env.DB.prepare(`SELECT namespace,payload,updated_at FROM aio_state WHERE namespace LIKE 'student:%' ORDER BY updated_at DESC LIMIT 1`).first(),ds=await env.DB.prepare(`SELECT character,trigger,decision,neurons,created_at FROM brain_decisions WHERE created_at>=? ORDER BY id DESC LIMIT 40`).bind(cutoff).all(),es=await env.DB.prepare(`SELECT character,event_type,action,target,reward,payload,created_at FROM brain_learning_events WHERE created_at>=? ORDER BY id DESC LIMIT 80`).bind(cutoff).all(),cs=await env.DB.prepare(`SELECT name,payload,received_at FROM character_status ORDER BY received_at DESC LIMIT 8`).all();let studentPayload={};try{studentPayload=sr&&sr.payload?JSON.parse(sr.payload):{};}catch{}const chars=(cs.results||[]).map(r=>{try{const p=JSON.parse(r.payload)||{};return {name:r.name,ctype:text(p.ctype,32),role:text(p.role,32),level:number(p.level),xpPerHour:number(p.xpPerHour),goldPerHour:number(p.goldPerHour),map:text(p.map,80),active:Boolean(p.active),rip:Boolean(p.rip),farmHealth:p.farmHealth&&typeof p.farmHealth==="object"?{visible:number(p.farmHealth.visible),competitors:number(p.farmHealth.competitors),xpPerHour:number(p.farmHealth.xpPerHour),expectedXpPerHour:number(p.farmHealth.expectedXpPerHour),goldPerHour:number(p.farmHealth.goldPerHour),safetyPct:number(p.farmHealth.safetyPct),goal:p.farmHealth.goal||null}:null};}catch{return {name:r.name};}}),aliases=researchAliasMap(chars,anonymize),rsummary=researchMapObject(researchSummary(studentPayload),aliases),decisions=(ds.results||[]).map(r=>{let q={};try{q=JSON.parse(r.decision)||{};}catch{}return {character:aliases[r.character]||researchReplaceNames(r.character,aliases),trigger:researchReplaceNames(r.trigger,aliases),action:researchText(q.action,40),target:researchReplaceNames(q.target,aliases),confidence:number(q.confidence),reason:researchReplaceNames(q.reason,aliases),lesson:researchReplaceNames(q.lesson,aliases),neurons:number(r.neurons),createdAt:number(r.created_at)};}),events=(es.results||[]).map(r=>{let p={};try{p=JSON.parse(r.payload)||{};}catch{}const metric=x=>x&&typeof x==="object"?{xp:number(x.xp),gold:number(x.gold),free:number(x.free),safety:number(x.safety),errors:number(x.errors),rip:Boolean(x.rip),partyComplete:Boolean(x.partyComplete),exploreVisits:number(x.exploreVisits),zoneSamples:number(x.zoneSamples)}:null;return {character:aliases[r.character]||researchReplaceNames(r.character,aliases),eventType:researchText(r.event_type,40),action:researchText(r.action,40),target:researchReplaceNames(r.target,aliases),reward:number(r.reward),before:metric(p.before),after:metric(p.after),source:researchText(p.source,40),policyRole:researchText(p.policyRole,30),policyGeneration:number(p.policyGeneration),createdAt:number(r.created_at)};}),safeChars=chars.map(c=>({...c,name:aliases[c.name]||researchReplaceNames(c.name,aliases),map:researchReplaceNames(c.map,aliases),farmHealth:researchMapObject(c.farmHealth,aliases)}));const data={schema:1,source:"cloudflare-d1",profile,profileLabel:RESEARCH_PROFILES[profile].label,generatedAt:Date.now(),windowHours:hours,anonymized:anonymize,studentResearch:rsummary,characters:safeChars,teacherDecisions:decisions,learningEvents:events,highlights:(rsummary&&rsummary.highlights)||[],dataLimitations:["Web-Brief nutzt D1-Sync und keine vollständigen lokalen Roh-Auditlogs.","Keine neuronalen Gewichtsmatrizen ausgegeben.","Secrets/Auth-Felder werden verworfen oder redigiert."]},prompt=`AiO Research Bridge · ${RESEARCH_PROFILES[profile].label}\n\n${RESEARCH_PROFILES[profile].task}\n\nArbeitsregeln für die Analyse:\n- Nutze nur die gelieferten Daten als Tatsachengrundlage und markiere Unsicherheit/Datenlücken.\n- Priorisiere 24/7-Stabilität und Sicherheit vor EXP/h und Gold/h.\n- Trenne deterministische Bot-Codeänderungen von Änderungen am neuronalen Brain.\n- Nenne je Empfehlung erwarteten Nutzen, Risiko und einen prüfbaren Test.\n- Suche nach wiederkehrenden Fehlern, Reward-Verschlechterung, Overconfidence, unnötigen Teacher-Aufrufen und Merchant-/Inventar-Loops.\n- Schlage keine Änderung nur um der Änderung willen vor.\n\nStrukturierte Bot-Daten:\n\`\`\`json\n${JSON.stringify(data,null,2)}\n\`\`\`\n\nBitte liefere eine priorisierte technische Analyse und – wenn sinnvoll – einen konkreten Plan für die nächste Bot-Version.`;return json({ok:true,profile,profileLabel:RESEARCH_PROFILES[profile].label,generatedAt:data.generatedAt,anonymized:anonymize,prompt,data});}
'''
w=w.replace(marker,server+marker,1)
# route
old='if(request.method==="GET"&&url.pathname==="/api/brain-status")return handleBrainStatus(request,env);'
new=old+'if(request.method==="GET"&&url.pathname==="/api/research-brief")return handleResearchBrief(request,env);'
assert old in w
w=w.replace(old,new,1)
# embed dashboard exactly by replacing const DASHBOARD_HTML assignment
html=dashp.read_text()
start=w.index('const DASHBOARD_HTML = ')
semi=w.index(';\n',start)+1
w=w[:start]+'const DASHBOARD_HTML = '+json.dumps(html,ensure_ascii=False)+';'+w[semi:]
wp.write_text(w)
